// Este nodo corre DESPUÉS de TurnoReclutador (Postgres) o directo desde If5

const trigger = $('Recibido desde Analizador').first().json;
const agenda = trigger._agenda || {};

// Si solo hay un reclutador, ya está resuelto y devolvemos la agenda directamente
if (!agenda.grupo_turno) {
    return [{
        json: agenda
    }];
}

// Si hay varios reclutadores, el índice viene de Postgres en $json
const turnoIndex = $json.ultimo_index ?? 0;

const candidatos = JSON.parse(agenda.candidatos_turno);
const asignado = candidatos[turnoIndex];

return [{
    json: {
        nombre_reclutador: asignado.nombre,
        telefono_reclutador: asignado.telefono,
        calendar_id: asignado.calendar_id,
        vacante_detectada: agenda.vacante_detectada,
        nave_candidato: agenda.nave_candidato,
        grupo_turno: agenda.grupo_turno,
        turno_index: turnoIndex
    }
}];

// 1. Obtenemos los datos desde el contexto del chat
const dbData = $('Recibido desde Analizador').first().json._candidato || {};
const chatData = $input.first().json;

// 🔮 MAGIA: Tomamos el reclutador EXACTO que ya asignó el sistema de turnos
const reclutadorAsignado = $('ResolverReclutador').first()?.json || {};

let nombreCandidato = dbData.nombre_ine || dbData.nombre_chat || "Candidato";
let telefonoCandidato = $('Recibido desde Analizador').first().json._contacto?.number || dbData.telefono || "0000000000";
let fechaCita = chatData.fecha_entrevista_detectada || "Fecha por confirmar";

// 💡 Transformar la fecha fea "2026-07-17T16:00:00" a texto bonito
if (fechaCita && fechaCita.includes("T")) {
    try {
        const [fechaParte, horaParte] = fechaCita.split('T');
        const [anio, mes, dia] = fechaParte.split('-');
        let [hora, minuto] = horaParte.split(':');

        const meses = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
        const nombreMes = meses[parseInt(mes, 10) - 1];

        let ampm = "AM";
        let horaInt = parseInt(hora, 10);
        if (horaInt >= 12) {
            ampm = "PM";
            if (horaInt > 12) horaInt -= 12;
        }
        if (horaInt === 0) horaInt = 12;

        fechaCita = `${parseInt(dia, 10)} de ${nombreMes} de ${anio} a las ${horaInt}:${minuto} ${ampm}`;
    } catch(e) {}
}

let naveCandidato = dbData.nave_interes || "No especificada";
let resumenIA = "Sin resumen previo disponible.";
const rawResumen = dbData.resumen_ia || "";

let vacanteDesdeResumen = "";

if (rawResumen.includes("MEMORY_UPDATE")) {
    const bloqueResumen = rawResumen.split("MEMORY_UPDATE")[1]?.split("|")?.[1]?.trim() || rawResumen;
    resumenIA = expandirResumenComprimido(bloqueResumen);
} else {
    resumenIA = rawResumen || "Sin resumen previo disponible.";

    // 💡 NUEVO: Si el resumen ya viene expandido en texto, lo extraemos de ahí
    if (resumenIA.includes("Vacante: ")) {
        const match = resumenIA.match(/Vacante:\s*([^.]+)/);
        if (match && match[1] !== 'N/D') {
            vacanteDesdeResumen = match[1].trim();
        }
    }
}

function expandirResumenComprimido(texto) {
    if (!texto) return "Sin resumen previo disponible.";
    const esFormatoComprimido = /\bN:|V:|E:|Priv:|CV:|INE:|RFC:|Cita:/.test(texto);
    if (!esFormatoComprimido) return texto;

    const get = (regex) => {
        const m = texto.match(regex);
        return m ? m[1].trim() : null;
    };

    const nombre = get(/N:([^V]*?)(?=\s+V:|$)/);
    const vacante = get(/V:([^E]*?)(?=\s+E:|$)/);
    const etapa = get(/E:([^P]*?)(?=\s+Priv:|$)/);
    const privacidad = get(/Priv:([^\s]*)/);
    const cv = get(/CV:([^\s]*)/);
    const ine = get(/INE:([^\s]*)/);
    const rfc = get(/RFC:([^\s]*)/);
    const cita = get(/Cita:([^N]*?)(?=\s+Notas:|$)/);
    const notas = get(/Notas:(.*)$/);

    // Guardamos la vacante que extrajo la IA si estaba comprimido
    if (vacante && vacante !== 'N/D') vacanteDesdeResumen = vacante;

    const siNo = (v) => v === 'S' ? 'Sí' : v === 'N' ? 'No' : (v || 'N/D');

    let partes = [];
    if (nombre) partes.push(`Nombre: ${nombre}`);
    if (vacante) partes.push(`Vacante: ${vacante}`);
    if (etapa) partes.push(`Etapa: ${etapa}`);
    if (privacidad) partes.push(`Privacidad aceptada: ${siNo(privacidad)}`);
    if (cv) partes.push(`CV recibido: ${siNo(cv)}`);
    if (ine) partes.push(`INE recibido: ${siNo(ine)}`);
    if (rfc) partes.push(`RFC recibido: ${siNo(rfc)}`);
    if (cita) partes.push(`Cita: ${cita.trim() === 'N' ? 'pendiente' : cita.trim()}`);
    if (notas) partes.push(`Notas: ${notas.trim()}`);

    return partes.length ? partes.join('. ') + '.' : texto;
}

// Limpiar espacios en blanco (ej: " ") que arruinan la vacante
let vacInteres = dbData.vacante_interes?.trim();
let vacDetectada = chatData.vacante_detectada?.trim();

// 💡 Toma la vacante detectada, o la de interés, o la del resumen de la IA
let vacanteDetectada = vacDetectada || vacInteres || vacanteDesdeResumen || "General";

// 💡 Parsear y formatear Filtros Técnicos para que se vea bonito
let ft = dbData.filtros_tecnicos;
let filtrosTecnicos = "Pendiente";
if (ft) {
    if (typeof ft === 'string') {
        try { ft = JSON.parse(ft); } catch(e){}
    }
    if (typeof ft === 'object' && ft !== null) {
        filtrosTecnicos = `Viable: ${ft.viable ? '✅ Sí' : '❌ No'}\nMotivo: ${ft.motivo || 'N/A'}`;
    } else {
        filtrosTecnicos = ft;
    }
}

// 2. Extraemos los datos del reclutador que ganó el turno
let nombreReclutador = reclutadorAsignado.nombre_reclutador || "Equipo de Reclutamiento";
let telefonoDestino = reclutadorAsignado.telefono_reclutador || "5213332012658";

// 3. ARMAR EL MENSAJE DE ÉXITO
let mensaje_alerta = `📅 *¡NUEVA ENTREVISTA AGENDADA!* \n\nHola ${nombreReclutador}, el bot acaba de cerrar una cita con éxito:\n\n👤 *Candidato:* ${nombreCandidato}\n📱 *Tel:* wa.me/${telefonoCandidato}\n💼 *Vacante:* ${vacanteDetectada}\n🏢 *Nave/Sucursal:* ${naveCandidato}\n⏰ *Fecha:* ${fechaCita}\n\n📝 *RESUMEN DEL CANDIDATO (IA):*\n${resumenIA}\n\n⚙️ *FILTROS TÉCNICOS:*\n_Todos los documentos (CV, INE, RFC) ya están listos y cargados en la plataforma.

return {
    json: {
        telefono_destino: telefonoDestino.replace('@c.us', ''),
        mensaje_alerta: mensaje_alerta
    }
};

// 1. OBTENER DATOS DEL USUARIO
const dbData = $('Recibido desde Analizador').first().json._candidato || {};
const infoWhatsapp = $('Recibido desde Analizador').first().json._contacto?.[0] || {};

// 🌟 MAGIA: Tomamos el reclutador EXACTO que ya asignó el sistema de turnos
const reclutadorAsignado = $('ResolverReclutador').first()?.json || {};

// 2. BÚSQUEDA DEL MENSAJE ORIGINAL
let ultimoMensajeUsuario = "No se detectó texto";
try {
    const webhookBody = $('Recibido desde Analizador').first().json._webhook.body;
    ultimoMensajeUsuario = webhookBody.payload?.body || webhookBody.message?.body || webhookBody.body || "Mensaje multimedia o sin texto";
} catch(e) {}

// 3. RESCATAR NOMBRE Y MOTIVO DE LA IA
const rawAiResponse = $('AI Chat').first()?.json?.output || $('AI Chat').first()?.json?.text || "";
let nombreRescatadoIA = "";
let motivoRescatadoIA = "El usuario solicitó hablar con un humano.";

if (rawAiResponse.includes('HUMAN_ALERT')) {
    let fragmento = rawAiResponse.split('HUMAN_ALERT')[1].split('MEMORY_UPDATE')[0];
    let partes = fragmento.split('|').map(p => p.trim());
    if (partes.length >= 4) { nombreRescatadoIA = partes[1]; motivoRescatadoIA = partes[2]; }
    else if (partes.length === 3) { nombreRescatadoIA = partes[1]; }
}

let nombre = dbData.nombre || nombreRescatadoIA || "Candidato";
const telefono = dbData.telefono || infoWhatsapp.id?.user || "0000000000";
let vacante = dbData.vacante_interes || "General";

// 4. USAR LOS DATOS DEL NODO RESOLVER_RECLUTADOR
const nombreDestino = reclutadorAsignado.nombre_reclutador || "Equipo de Reclutamiento";
const telefonoDestino = reclutadorAsignado.telefono_reclutador || "5213323379399";

// 5. SALIDA
return {
    json: {
        telefono_destino: telefonoDestino.replace('@c.us', ''),
        nombre_candidato: nombre,          
        telefono_candidato: telefono,      
        vacante: vacante,                 
        mensaje_alerta: `🚨 *SOLICITUD DE ATENCIÓN HUMANA*\n\nHola ${nombreDestino}, este usuario pide hablar con un reclutador:\n\n👤 *${nombre}*\n📱 wa.me/${telefono}\n💼 Interés: ${vacante}\n\n💬 *Mensaje literal:* "${ultimoMensajeUsuario}"\n\n🤖 *Resumen Sofía:* _${motivoRescatadoIA}_`
    }
};

return [{
  json: {
    original: $json,
    contacto: $('Recibido desde Analizador').first().json._contacto,
    number: $('Recibido desde Analizador').first().json._contacto?.number,
    replacement: [ $('Recibido desde Analizador').first().json._contacto?.number ?? '' ]
  }
}];

// ============================================================
// PARSER DE CÓDIGOS ESPECIALES (antes en /home/node/virgo_files/functions/parse_special_codes.js,
// ahora inline para no depender de require() en el nodo)
// ============================================================

const SPECIAL_CODES = {
  NAME_UPDATE: { pattern: /NAME_UPDATE\s*\|\s*([^|]+)\s*\|/i, action: 'update_name', field: 'nombre' },
  VACANTE_UPDATE: { pattern: /VACANTE_UPDATE\s*\|\s*([^|]+)\s*\|/i, action: 'update_vacante', field: 'vacante_interes' },
  CITA_CONFIRMADA: { pattern: /CITA_CONFIRMADA\s*\|/i, action: 'cita_confirmada', field: 'fecha_cita_detectada' },
  CON_CV: { pattern: /CON_CV\s*\|\s*([^|]+)\s*\|/i, action: 'cv_recibido', field: 'tiene_cv' },
  CV_MANUAL: { pattern: /CV_MANUAL\s*\|\s*(\{[^}]+\})/i, action: 'cv_manual', field: 'cv_data', isJSON: true },
  HUMAN_ALERT: { pattern: /HUMAN_ALERT\s*\|\s*([^|]+)\s*\|/i, action: 'escalate_to_human', field: 'escalation_reason' },
  MEMORY_UPDATE: { pattern: /MEMORY_UPDATE\s*\|\s*([^|]+)\s*\|/i, action: 'update_memory', field: 'resumen_ia' },
  CITA_CANCELADA: { pattern: /CITA_CANCELADA\s*\|/i, action: 'cita_cancelada', field: 'estado' }
};
const CODE_ENTRIES = Object.entries(SPECIAL_CODES);

function extractCode(text, codeName, codeConfig) {
  const match = text.match(codeConfig.pattern);
  if (!match) return null;
  let value = match[1]?.trim();
  if (codeConfig.isJSON && value) {
    try { value = JSON.parse(value); }
    catch (e) { console.error(`⚠️ Error JSON ${codeConfig.action}:`, value); return null; }
  }
  return { code: codeName, action: codeConfig.action, field: codeConfig.field, value, raw_match: match[0] };
}

function cleanMessage(text, detectedCodes) {
  if (!detectedCodes.length) return (typeof text === 'string' ? text : '').trim();
  let cleaned = typeof text === 'string' ? text : '';
  for (const code of detectedCodes) cleaned = cleaned.replace(code.raw_match, '');
  return cleaned.trim();
}

function generateDatabaseUpdates(detectedCodes) {
  const updates = {};
  const actions = [];
  for (const code of detectedCodes) {
    switch (code.action) {
      case 'update_name':
        updates.nombre = code.value;
        updates.nombre_confirmado = true;
        actions.push({ type: 'database_update', table: 'candidatos', field: 'nombre', value: code.value });
        break;
      case 'update_vacante':
        updates.vacante_interes = code.value;
        updates.estado = 'INTERESADO';
        actions.push({ type: 'database_update', table: 'candidatos', field: 'vacante_interes', value: code.value });
        break;
      case 'cita_confirmada':
        updates.estado = 'CITA_AGENDADA';
        updates.fecha_ultima_cita = new Date().toISOString();
        actions.push({ type: 'database_update', table: 'candidatos', field: 'estado', value: 'CITA_AGENDADA' });
        actions.push({ type: 'send_confirmation', channel: 'whatsapp' });
        break;
      case 'cv_recibido':
        updates.tiene_cv = true;
        updates.estado = 'CV_RECIBIDO';
        updates.vacante_cv = code.value;
        actions.push({ type: 'database_update', table: 'candidatos', field: 'tiene_cv', value: true });
        break;
      case 'cv_manual': {
        const cvManualStr = JSON.stringify(code.value);
        updates.cv_manual = cvManualStr;
        updates.cv_manual_obj = code.value;
        updates.tiene_cv = true;
        updates.estado = 'CV_MANUAL';
        actions.push({ type: 'database_update', table: 'candidatos', field: 'cv_manual', value: cvManualStr });
        break;
      }
      case 'escalate_to_human':
        updates.estado = 'ESCALADO';
        updates.escalation_reason = code.value;
        updates.escalated_at = new Date().toISOString();
        actions.push({ type: 'alert_human', priority: 'high', reason: code.value });
        break;
      case 'update_memory':
        updates.resumen_ia = code.value;
        updates.ultima_actualizacion = new Date().toISOString();
        actions.push({ type: 'database_update', table: 'candidatos', field: 'resumen_ia', value: code.value });
        break;
      case 'cita_cancelada':
        updates.estado = 'INTERESADO';
        actions.push({ type: 'database_update', table: 'candidatos', field: 'estado', value: 'INTERESADO' });
        break;
    }
  }
  return { updates, actions };
}

function parseSpecialCodes(aiResponse) {
  if (!aiResponse) {
    return { message_to_user: "", has_special_codes: false, detected_codes: [], pending_actions: [] };
  }

  let textToParse = "";
  let jsonObj = null;

  if (typeof aiResponse === 'object') {
    jsonObj = aiResponse;
    textToParse = JSON.stringify(aiResponse);
  } else if (typeof aiResponse === 'string') {
    const cleanStr = aiResponse.replace(/```json/gi, '').replace(/```/g, '').trim();
    textToParse = cleanStr;
    if (cleanStr.startsWith('{') && cleanStr.endsWith('}')) {
      try { jsonObj = JSON.parse(cleanStr); } catch (e) {}
    }
  } else {
    textToParse = String(aiResponse);
  }

  const detectedCodes = [];
  for (const [codeName, codeConfig] of CODE_ENTRIES) {
    const extracted = extractCode(textToParse, codeName, codeConfig);
    if (extracted) detectedCodes.push(extracted);
  }

  let cleanedMessage = cleanMessage(textToParse, detectedCodes);
  if (jsonObj?.mensaje_al_usuario) cleanedMessage = jsonObj.mensaje_al_usuario;

  const { updates, actions } = generateDatabaseUpdates(detectedCodes);

  if (jsonObj?.memoria_update) {
    updates.resumen_ia = jsonObj.memoria_update;
    actions.push({ type: 'database_update', table: 'candidatos', field: 'resumen_ia', value: jsonObj.memoria_update });
  }

  return {
    message_to_user: cleanedMessage,
    detected_codes: detectedCodes.map(c => ({ code: c.code, action: c.action, value: c.value })),
    database_updates: updates,
    pending_actions: actions,
    text_para_whatsapp: cleanedMessage,
    nombre_detectado: updates.nombre,
    vacante_detectada: updates.vacante_interes,
    cita_creada: actions.some(a => a.type === 'send_confirmation'),
    cita_cancelada: detectedCodes.some(c => c.action === 'cita_cancelada'),
    motivo_final: updates.escalation_reason,
    es_cv_manual: !!updates.cv_manual,
    datos_cv_manual: updates.cv_manual_obj || null,
    resumen_generado: updates.resumen_ia,
    has_special_codes: detectedCodes.length > 0 || !!jsonObj?.memoria_update,
    processed_at: new Date().toISOString(),
    _original_response: aiResponse
  };
}

// ============================================================
// LÓGICA DEL NODO
// ============================================================

// 1. Obtener datos de entrada (soporta objeto JSON directo o texto string)
const item = $input.first();
let rawInput = item.json.output || item.json.text || item.json.message || item.json;

if (typeof rawInput === 'object' && rawInput !== null) {
  if (typeof rawInput.output === 'string') rawInput = rawInput.output;
  else if (typeof rawInput.text === 'string') rawInput = rawInput.text;
  else if (typeof rawInput.message === 'string') rawInput = rawInput.message;
}

let inputForParser = rawInput;
let jsonParsed = null;

if (typeof rawInput === 'string') {
  const trimmed = rawInput.trim();

  // Intentar parsear toda la cadena como JSON (caso más común)
  if (trimmed.startsWith('{')) {
    try { jsonParsed = JSON.parse(trimmed); inputForParser = jsonParsed; } catch (e) {}
  }

  // Si falló, buscar JSON incrustado en texto con brace-matching seguro
  if (!jsonParsed) {
    const keyIdx = trimmed.indexOf('"mensaje_al_usuario"');
    if (keyIdx !== -1) {
      const startBrace = trimmed.lastIndexOf('{', keyIdx);
      if (startBrace !== -1) {
        let depth = 0;
        let endIdx = -1;
        for (let i = startBrace; i < trimmed.length; i++) {
          if (trimmed[i] === '{') depth++;
          else if (trimmed[i] === '}') { depth--; if (depth === 0) { endIdx = i; break; } }
        }
        if (endIdx !== -1) {
          try { jsonParsed = JSON.parse(trimmed.substring(startBrace, endIdx + 1)); inputForParser = jsonParsed; } catch (e) {}
        }
      }
    }
  }
} else if (typeof rawInput === 'object' && rawInput !== null) {
  jsonParsed = rawInput;
  inputForParser = rawInput;
}

// 2. Contexto — una sola lectura del nodo previo, reutilizada en todo el script
// (antes se llamaba $('Recibido desde Analizador').first() hasta 5 veces)
const analizador = $('Recibido desde Analizador').first().json;
const webhookData = analizador._webhook?.body?.payload || {};
const context = { phone: webhookData.from, executionId: $execution.id };

// 3. Ejecutar parser
const result = parseSpecialCodes(inputForParser, context);

// Si viene JSON estructurado con mensaje_al_usuario y memoria_update
if (jsonParsed) {
  if (jsonParsed.mensaje_al_usuario) {
    result.message_to_user = jsonParsed.mensaje_al_usuario;
    result.text_para_whatsapp = jsonParsed.mensaje_al_usuario;
  }
  if (jsonParsed.memoria_update) {
    result.resumen_generado = jsonParsed.memoria_update;
    result.database_updates = result.database_updates || {};
    result.database_updates.resumen_ia = jsonParsed.memoria_update;
  }

  const et = jsonParsed.etiquetas_internas || jsonParsed;
  if (et.actualizar_vacante || et.vacante_interes || et.vacante) {
    result.vacante_detectada = String(et.actualizar_vacante || et.vacante_interes || et.vacante).trim().toUpperCase();
  }
  if (et.actualizar_nave || et.nave_interes || et.nave) {
    result.nave_detectada = String(et.actualizar_nave || et.nave_interes || et.nave).trim().toUpperCase();
  }
  if (et.actualizar_nombre || et.nombre) {
    result.nombre_detectado = String(et.actualizar_nombre || et.nombre).trim();
  }
}

// ---------------------------------------------------------
// 4. PARCHES Y ETIQUETAS SECRETAS
// ---------------------------------------------------------

const aiResponseStr = typeof rawInput === 'object' ? JSON.stringify(rawInput) : String(rawInput || '');

if (result.message_to_user && typeof result.message_to_user === 'string') {
  result.message_to_user = result.message_to_user.split('MEMORY_UPDATE')[0].trim();
}

const vacMatch = aiResponseStr.match(/(?:ACTUALIZAR_VACANTE|"actualizar_vacante"|"vacante_interes")\s*[:|^"]\s*([^"|\n,}]+)/i);
if (vacMatch?.[1]) {
  const val = vacMatch[1].trim().replace(/^["\s|]+|["\s|]+$/g, '');
  if (val && val.toUpperCase() !== 'GENERAL' && val.toUpperCase() !== 'NINGUNA') {
    result.vacante_detectada = val.toUpperCase();
  }
}

const naveMatch = aiResponseStr.match(/(?:ACTUALIZAR_NAVE|"actualizar_nave"|"nave_interes")\s*[:|^"]\s*([^"|\n,}]+)/i);
if (naveMatch?.[1]) {
  const val = naveMatch[1].trim().replace(/^["\s|]+|["\s|]+$/g, '');
  if (val && val.toUpperCase() !== 'PENDIENTE') {
    result.nave_detectada = val.toUpperCase();
  }
}

const nomMatch = aiResponseStr.match(/(?:ACTUALIZAR_NOMBRE|"actualizar_nombre")\s*[:|^"]\s*([^"|\n,}]+)/i);
if (nomMatch?.[1]) {
  const val = nomMatch[1].trim().replace(/^["\s|]+|["\s|]+$/g, '');
  if (val && val !== 'Desconocido' && val !== 'Candidato') {
    result.nombre_detectado = val;
  }
}

if (aiResponseStr.includes('PRIVACIDAD_ACEPTADA')) result.acepto_privacidad = true;
if (aiResponseStr.includes('CITA_CANCELADA')) result.cita_cancelada = true;
if (aiResponseStr.includes('ENVIAR_UBICACION')) result.enviar_ubicacion = true;

const citaMatch = aiResponseStr.match(/CITA_CONFIRMADA[\s:|]*(.*?)([|\n]|$)/i);
if (citaMatch?.[1]) {
  result.fecha_entrevista_detectada = citaMatch[1].replace(/\|/g, '').trim();
}

// HUMAN_ALERT
const humanAlertParts = aiResponseStr.split(/HUMAN_ALERT/i);
if (humanAlertParts.length > 1) {
  const mensajeHumanoDefault =
    "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";

  let fragmento = (humanAlertParts[1].split(/MEMORY_UPDATE/i)[0] || "").trim();
  fragmento = fragmento.replace(/^\s*\|\s*/, "").trim();
  const partesRaw = fragmento.split("|").map(p => p.trim());

  // Antes: hasta 3 llamadas a $('Recibido desde Analizador').first() por rama (x2 ramas).
  // Ahora: se calcula una sola vez, a partir del `analizador` ya cacheado.
  const nombreCandidatoFallback =
    analizador._candidato?.nombre_chat ||
    analizador._candidato?.nombre_ine ||
    analizador._candidato?.nombre_solicitud ||
    "Candidato";

  let nombre = "", resumen = "", mensajeVisible = "";
  const primerCampo = partesRaw[0] || "";
  const primerCampoPareceResumen =
    /candidato|documento|constancia|rfc|ine|cv|solicit|agend|conflict|no cuenta|no tiene/i.test(primerCampo);

  if (partesRaw.length >= 3 && !primerCampoPareceResumen) {
    nombre = partesRaw[0];
    resumen = partesRaw[1];
    mensajeVisible = partesRaw.slice(2).join(" | ").trim();
  } else if (partesRaw.length >= 2 && primerCampoPareceResumen) {
    nombre = nombreCandidatoFallback;
    resumen = partesRaw[0];
    mensajeVisible = partesRaw.slice(1).join(" | ").trim();
  } else if (partesRaw.length >= 2) {
    nombre = partesRaw[0];
    resumen = partesRaw[1];
    mensajeVisible = mensajeHumanoDefault;
  } else {
    nombre = nombreCandidatoFallback;
    resumen = "El candidato solicitó apoyo de reclutamiento humano.";
    mensajeVisible = mensajeHumanoDefault;
  }

  if (
    !mensajeVisible ||
    /^el candidato/i.test(mensajeVisible) ||
    /impidiendo el agendamiento/i.test(mensajeVisible) ||
    /solicitó escalamiento/i.test(mensajeVisible)
  ) {
    mensajeVisible = mensajeHumanoDefault;
  }

  result.human_alert_nombre = nombre.trim();
  result.human_alert_resumen = resumen.trim();
  result.message_to_user = mensajeVisible.trim();
}

// CV_MANUAL
const cvManualMatch = aiResponseStr.match(/CV_MANUAL[\s:|]*(\{[\s\S]*?\})/i);
if (cvManualMatch?.[1]) {
  try {
    const jsonLimpio = cvManualMatch[1]
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .replace(/[\n\r\t]/g, ' ')
      .trim();
    const cvData = JSON.parse(jsonLimpio);
    result.experiencia_manual = cvData.experiencia;
    result.vacante_manual = cvData.vacante;
    result.datos_cv_manual = cvData;
    result.es_cv_manual = true;
    if (cvData.nombre && cvData.nombre !== "Desconocido") {
      result.nombre_detectado = cvData.nombre;
    }
  } catch (e) {
    result.datos_cv_manual = { error: "La IA formateó mal el JSON", experiencia: "Candidato llenó solicitud manual por chat." };
    result.es_cv_manual = true;
  }
}

// RESPUESTAS_FILTRO
const filtroMatch = aiResponseStr.match(/RESPUESTAS_FILTRO[\s:|]*([\s\S]*?)(?=\n[A-Z_]+\s*\||$)/i);
if (filtroMatch?.[1]) {
  result.respuestas_filtro_detectadas = filtroMatch[1].replace(/\|/g, '').trim();
}

// ---------------------------------------------------------
// 5. LIMPIEZA VISUAL PROFUNDA (sin ReDoS)
// ---------------------------------------------------------

if (result.message_to_user && typeof result.message_to_user === 'string') {
  // Cortar bloque JSON directo si se filtró
  const jsonKeyIdx = result.message_to_user.indexOf('"mensaje_al_usuario"');
  if (jsonKeyIdx !== -1) {
    const startB = result.message_to_user.lastIndexOf('{', jsonKeyIdx);
    if (startB !== -1) {
      result.message_to_user = result.message_to_user.substring(0, startB);
    }
  }

  // Antes: 8 llamadas encadenadas de .replace() (8 pasadas completas sobre el string).
  // Ahora: un solo regex combinado, una sola pasada.
  const CLEANUP_RE = /ACTUALIZAR_(?:NOMBRE|VACANTE|NAVE)\s*\|\s*[^|\n]+(?:\||)|PRIVACIDAD_ACEPTADA\s*\|?|CITA_CONFIRMADA[\s:|]*.*?(?:[|\n]|$)|CITA_CANCELADA[\s:|]*.*?(?:[|\n]|$)|ENVIAR_UBICACION[\s:|]*.*?(?:[|\n]|$)|```json|```/gi;
  result.message_to_user = result.message_to_user.replace(CLEANUP_RE, '').trim();

  if (result.fecha_entrevista_detectada) {
    result.message_to_user = result.message_to_user
      .replace(result.fecha_entrevista_detectada, '')
      .replace(/\|/g, '')
      .trim();
  }

  if (
    /^el candidato/i.test(result.message_to_user) ||
    result.message_to_user.includes("impidiendo el agendamiento") ||
    result.message_to_user.includes("Solicitó escalamiento") ||
    result.message_to_user.includes("solicitó escalamiento")
  ) {
    result.message_to_user =
      "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";
  }

  if (result.message_to_user.includes("|")) {
    const partes = result.message_to_user.split("|").map(p => p.trim()).filter(Boolean);
    result.message_to_user = partes[partes.length - 1] ||
      "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";
  }

  result.message_to_user = result.message_to_user.replace(/^[|\s]+/, '').trim();
}

if (!result.message_to_user || typeof result.message_to_user !== 'string' || result.message_to_user.trim() === "") {
  result.message_to_user = "¡Hola! 😊 ¿En qué puedo ayudarte hoy o qué duda tienes sobre nuestras vacantes?";
}

// ---------------------------------------------------------
// 6. SPLIT DE MENSAJES Y MENÚ CADA 3 MENSAJES
// ---------------------------------------------------------

let mensajes = result.message_to_user.includes('[SPLIT]')
  ? result.message_to_user.split(/\[SPLIT\]/i).map(m => m.trim()).filter(m => m !== "")
  : [result.message_to_user];

// Antes: JSON.parse(JSON.stringify(result)) por cada mensaje (serialización completa).
// Ahora: clon superficial con spread, suficiente porque solo se sobrescribe
// message_to_user (campo de primer nivel) en cada copia.
let output = mensajes.map(msg => ({ json: { ...result, message_to_user: msg } }));

let mensajes_enviados = analizador._candidato?.mensajes_bot_enviados || 0;
if (mensajes_enviados % 3 === 0 && output.length > 0) {
  output[output.length - 1].json.message_to_user += '\n\n_(Escribe "Menú" para volver al menú principal o "Cambiar sucursal" para cambiar de nave)_';
}

return output;

